  def icon(name, class: "w-5 h-5", stroke_width: 1.5)
    body = ICONS[name.to_sym] or return "".html_safe
    klass = binding.local_variable_get(:class)
    %(<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="#{stroke_width}" stroke-linecap="round" stroke-linejoin="round" class="#{klass}" aria-hidden="true">#{body}</svg>).html_safe
  end
